function output = heartlib(M)
% output = heartlib(M)
%
%    ElementSets, BoundaryMatrices, UnsignedBoundaryMatrices, NonZeros, IndicatorVector from MeshConnectivity
%    Vertices, Edges from FundamentalPointCloudAccessors(M)
%    M ∈ EdgeMesh 
%    V, E = ElementSets( M )
%    `∂⁰` = BoundaryMatrices(M) 
%    `∂⁰ᵀ` = `∂⁰`ᵀ
%    `B⁰` = UnsignedBoundaryMatrices(M)
%    `B⁰ᵀ` = `B⁰`ᵀ
%    
%    
%    VertexOneRing(v) = vertexset(NonZeros(`B⁰` (`B⁰ᵀ` IndicatorVector({v})))) - {v} where v ∈ V
%    VertexOneRing(v) = vertexset(NonZeros(`B⁰` (`B⁰ᵀ` IndicatorVector(v)))) - v where v ⊂  V
%    
%    EdgeIndex(i, j) = eset_1 where i,j ∈ V,
%    eset = edgeset(NonZeros(`∂⁰ᵀ` IndicatorVector({i}))) ∩ edgeset(NonZeros(`∂⁰ᵀ` IndicatorVector({j})))
%    
    dimv_0 = M.n_vertices();
    dime_0 = M.n_edges();
    dimf_0 = M.n_faces();
    [V, E] = M.ElementSets();
    function output = FundamentalPointCloudAccessors(M)
    % output = FundamentalPointCloudAccessors(M)
    %
    %    ElementSets, BoundaryMatrices, UnsignedBoundaryMatrices, NonZeros, IndicatorVector  from MeshConnectivity
    %    
    %    M ∈ EdgeMesh 
    %    
    %    V, E = ElementSets( M )
    %    dee0 = BoundaryMatrices(M) 
    %    B0 = UnsignedBoundaryMatrices(M)
    %    B0T = B0ᵀ
    %    
    %    Vertices(S) = S₁ where S: CellularSet
    %    Edges(S)    = S₂ where S: CellularSet 
    %     
    %    Vertices(e) = vertexset(NonZeros(B0 IndicatorVector({e}))) where e ∈ E
    %    Vertices(H) = vertexset(NonZeros(B0 IndicatorVector(H))) where H ⊂ E
    %     
    %    Edges(v) = edgeset(NonZeros(B0T IndicatorVector({v}))) where v ∈ V 
        dimv_0 = M.n_vertices();
        dime_0 = M.n_edges();
        dimf_0 = M.n_faces();
        [V, E] = M.ElementSets();
        % dee0 = BoundaryMatrices(M)
        dee0 = M.BoundaryMatrices();
        % B0 = UnsignedBoundaryMatrices(M)
        B0 = M.UnsignedBoundaryMatrices();
        % B0T = B0ᵀ
        B0T = B0';
        function [ret] = Vertices(S)
            ret = S(1);
        end
        function [ret_1] = Edges(S)
            ret_1 = S(2);
        end
        function [ret_2] = Vertices_0(e)
            assert(numel(e) == 1);
            assert( ismember(e, E) );
            ret_2 = NonZeros(B0 * indicator([e], M.n_edges()));
        end
        function [ret_3] = Vertices_1(H)
            ret_3 = NonZeros(B0 * indicator(H, M.n_edges()));
        end
        function [ret_4] = Edges_0(v)
            assert(numel(v) == 1);
            assert( ismember(v, V) );
            ret_4 = NonZeros(B0T * indicator([v], M.n_vertices()));
        end
        output.V = V;
        output.E = E;
        output.dee0 = dee0;
        output.B0 = B0;
        output.B0T = B0T;
        output.Vertices = @Vertices;
        output.Edges = @Edges;
        output.Vertices_0 = @Vertices_0;
        output.Vertices_1 = @Vertices_1;
        output.Edges_0 = @Edges_0;
        output.M = M;
    end
    FundamentalPointCloudAccessors_ = FundamentalPointCloudAccessors(M);
    Vertices = @FundamentalPointCloudAccessors_.Vertices;
    Vertices_0 = @FundamentalPointCloudAccessors_.Vertices_0;
    Vertices_1 = @FundamentalPointCloudAccessors_.Vertices_1;
    Edges = @FundamentalPointCloudAccessors_.Edges;
    Edges_0 = @FundamentalPointCloudAccessors_.Edges_0;
    % `∂⁰` = BoundaryMatrices(M)

    dee0 = M.BoundaryMatrices();
    % `∂⁰ᵀ` = `∂⁰`ᵀ

    dee0T = dee0';
    % `B⁰` = UnsignedBoundaryMatrices(M)

    B0 = M.UnsignedBoundaryMatrices();
    % `B⁰ᵀ` = `B⁰`ᵀ

    B0T = B0';
    function [ret] = VertexOneRing(v)
        assert(numel(v) == 1);
        assert( ismember(v, V) );

        ret = setdiff(NonZeros(B0 * (B0T * indicator([v], M.n_vertices()))), [v]);
    end

    function [ret_1] = VertexOneRing_0(v)
        ret_1 = setdiff(NonZeros(B0 * (B0T * indicator(v, M.n_vertices()))), v);
    end

    function [ret_2] = EdgeIndex(i, j)
        assert(numel(i) == 1);
        assert(numel(j) == 1);
        assert( ismember(i, V) );
        assert( ismember(j, V) );

        % eset = edgeset(NonZeros(`∂⁰ᵀ` IndicatorVector({i}))) ∩ edgeset(NonZeros(`∂⁰ᵀ` IndicatorVector({j})))
        eset = intersect(NonZeros(dee0T * indicator([i], M.n_vertices())), NonZeros(dee0T * indicator([j], M.n_vertices())));
        ret_2 = eset(1);
    end

    output.V = V;
    output.E = E;
    output.dee0 = dee0;
    output.dee0T = dee0T;
    output.B0 = B0;
    output.B0T = B0T;
    output.VertexOneRing = @VertexOneRing;
    output.VertexOneRing_0 = @VertexOneRing_0;
    output.EdgeIndex = @EdgeIndex;
    output.M = M;
end

